:root {
  --bg: #fbfaf7;
  --surface: #ffffff;
  --ink: #15171a;
  --ink-2: #3a3d42;
  --muted: #6b6f76;
  --line: #e4e2dc;
  --line-strong: #c9c6bd;
  --accent: #1f3b2d;
  --accent-ink: #ffffff;
  --accent-soft: #eaf0eb;
  --warn: #8a3a16;
  --warn-soft: #fbeadd;
  --shadow-sm: 0 1px 2px rgba(20, 22, 26, .06);
  --shadow-md: 0 8px 24px rgba(20, 22, 26, .08);
  --radius: 14px;
  --radius-sm: 8px;
  --maxw: 1200px;
  --font-sans: "Inter", "Helvetica Neue", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --font-serif: "Fraunces", "Cormorant Garamond", "Source Serif Pro", Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; }
a:focus-visible,
button:focus-visible,
input:focus-visible,
[tabindex="0"]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 8px; top: -40px;
  background: var(--accent); color: var(--accent-ink);
  padding: 8px 14px; border-radius: 6px;
  font-weight: 600; text-decoration: none;
  z-index: 1000;
  transition: top .15s ease;
}
.skip-link:focus { top: 8px; }

/* ===== Header ===== */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(251, 250, 247, .92);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 14px 24px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 24px;
  align-items: center;
}
.brand {
  display: inline-flex; align-items: center; gap: 8px;
  text-decoration: none; color: var(--ink);
}
.brand-mark { width: 26px; height: 26px; color: var(--accent); }
.brand-word {
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: .2px;
}

.primary-nav ul {
  display: flex; gap: 6px; list-style: none; padding: 0; margin: 0;
  justify-content: center;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  font-size: 14.5px;
  font-weight: 500;
  color: var(--ink-2);
  text-decoration: none;
  border-radius: 999px;
}
.primary-nav a:hover { background: var(--accent-soft); color: var(--accent); }

.header-actions {
  display: flex; align-items: center; gap: 8px;
  justify-self: end;
}
.search-form {
  display: flex; align-items: center;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px 4px 4px 14px;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.search-form:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.search-form input {
  border: 0; background: transparent;
  font: inherit; font-size: 14px;
  color: var(--ink); width: 180px; padding: 6px 0;
}
.search-form input:focus { outline: none; }
.search-form button {
  display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 32px;
  background: var(--ink); color: #fff;
  border: 0; border-radius: 999px; cursor: pointer;
}
.search-form button svg { width: 16px; height: 16px; }

.icon-btn {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  background: transparent;
  color: var(--ink);
  border: 1px solid transparent;
  border-radius: 999px;
  text-decoration: none;
  cursor: pointer;
}
.icon-btn:hover { background: var(--accent-soft); color: var(--accent); }
.icon-btn svg { width: 22px; height: 22px; }
.cart-count {
  position: absolute; top: 4px; right: 4px;
  min-width: 18px; height: 18px; padding: 0 5px;
  background: var(--accent); color: var(--accent-ink);
  font-size: 11px; font-weight: 700; line-height: 18px;
  text-align: center; border-radius: 999px;
}

/* ===== Hero ===== */
.hero {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 64px 24px 48px;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 48px;
  align-items: center;
}
.eyebrow {
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: 12px;
  font-weight: 600;
  color: var(--accent);
  margin: 0 0 14px;
}
.hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(40px, 5.6vw, 68px);
  line-height: 1.04;
  font-weight: 500;
  letter-spacing: -.01em;
  margin: 0 0 18px;
  color: var(--ink);
}
.hero-lead {
  font-size: 18px;
  color: var(--ink-2);
  max-width: 46ch;
  margin: 0 0 28px;
}
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; }

.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 12px 22px;
  font-size: 15px; font-weight: 600;
  border-radius: 999px;
  text-decoration: none;
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: transform .08s ease, background .15s ease, color .15s ease, border-color .15s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent); color: var(--accent-ink);
  border-color: var(--accent);
}
.btn-primary:hover { background: #15291f; border-color: #15291f; }
.btn-ghost {
  background: transparent; color: var(--ink);
  border-color: var(--line-strong);
}
.btn-ghost:hover { background: var(--ink); color: #fff; border-color: var(--ink); }

.hero-art {
  position: relative;
  aspect-ratio: 1 / 1;
  min-height: 320px;
}
.hero-card {
  position: absolute;
  border-radius: 18px;
  box-shadow: var(--shadow-md);
  overflow: hidden;
}
.hero-card-a {
  inset: 0 32% 30% 0;
  background:
    radial-gradient(120% 80% at 30% 30%, #fff5e1 0%, #e8c889 60%, #b18a3a 100%);
}
.hero-card-b {
  inset: 24% 0 0 38%;
  background:
    radial-gradient(120% 80% at 70% 30%, #f3efe6 0%, #cfd6c5 50%, #6c8071 100%);
}
.hero-card-c {
  inset: 56% 28% 0 18%;
  background:
    linear-gradient(135deg, #2c3a45 0%, #5a6b78 100%);
}

/* ===== Marquee benefits ===== */
.marquee {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}
.marquee ul {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 14px 24px;
  display: flex; flex-wrap: wrap;
  gap: 8px 36px;
  list-style: none;
  justify-content: center;
  font-size: 13.5px;
  color: var(--ink-2);
}
.marquee li { position: relative; }
.marquee li + li::before {
  content: "·";
  position: absolute; left: -22px; color: var(--line-strong);
}

/* ===== Sections ===== */
.section {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 72px 24px;
}
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 16px;
  margin-bottom: 28px;
}
.section-head h2 {
  font-family: var(--font-serif);
  font-size: clamp(28px, 3.4vw, 40px);
  font-weight: 500;
  margin: 0;
  letter-spacing: -.005em;
}
.link-arrow {
  color: var(--accent);
  font-weight: 600;
  font-size: 14.5px;
  text-decoration: none;
  white-space: nowrap;
}
.link-arrow:hover { text-decoration: underline; text-underline-offset: 4px; }

/* ===== Product grid ===== */
.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 24px;
}
.product {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .15s ease, box-shadow .15s ease, border-color .15s ease;
}
.product:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: var(--line-strong); }
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: var(--bg);
}
.product-badge {
  position: absolute; top: 12px; left: 12px;
  background: var(--ink); color: #fff;
  font-size: 11px; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
  padding: 5px 9px; border-radius: 999px;
}
.product-badge.sale { background: var(--warn); }
.product-fav {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  background: rgba(255,255,255,.92);
  border: 1px solid var(--line);
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer; color: var(--ink-2);
}
.product-fav:hover { color: var(--warn); }
.product-fav[aria-pressed="true"] { color: var(--warn); background: var(--warn-soft); }
.product-fav svg { width: 18px; height: 18px; }

.product-body {
  padding: 14px 16px 18px;
  display: flex; flex-direction: column; gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 12px; color: var(--muted);
  text-transform: uppercase; letter-spacing: .08em;
  margin: 0;
}
.product-name {
  font-size: 15.5px; font-weight: 600;
  margin: 0; color: var(--ink);
}
.product-name a { text-decoration: none; }
.product-name a:hover { text-decoration: underline; text-underline-offset: 3px; }
.product-meta {
  display: flex; justify-content: space-between; align-items: center;
  margin-top: auto; padding-top: 8px;
}
.price { font-weight: 600; color: var(--ink); }
.price del { color: var(--muted); font-weight: 400; margin-right: 6px; }
.rating {
  font-size: 12.5px; color: var(--ink-2);
  display: inline-flex; align-items: center; gap: 4px;
}
.rating .star { color: #c89b1e; }
.add-btn {
  margin: 0 16px 16px;
  padding: 10px 14px;
  background: var(--ink); color: #fff;
  border: 0; border-radius: 999px;
  font: inherit; font-size: 14px; font-weight: 600;
  cursor: pointer;
}
.add-btn:hover { background: #000; }

/* Product art (CSS-only "imagery") */
.art {
  width: 100%; height: 100%;
  background-color: #eee;
  background-size: cover;
  background-position: center;
}
.art-1 { background:
  radial-gradient(120% 90% at 30% 25%, #fff7e3 0%, #e9c481 55%, #9c6f2c 100%); }
.art-2 { background:
  radial-gradient(120% 90% at 70% 30%, #f1eee5 0%, #b8c2ac 55%, #4f6353 100%); }
.art-3 { background:
  linear-gradient(160deg, #e7eaf0 0%, #aab3c2 50%, #4b5566 100%); }
.art-4 { background:
  radial-gradient(120% 90% at 35% 35%, #f6e4dc 0%, #d39a85 55%, #843d29 100%); }
.art-5 { background:
  linear-gradient(150deg, #f0eadc 0%, #c5b48a 60%, #6b572f 100%); }
.art-6 { background:
  radial-gradient(120% 90% at 60% 30%, #e6efe9 0%, #8aa896 55%, #2f4a3c 100%); }
.art-7 { background:
  linear-gradient(150deg, #f4f1ec 0%, #cdc0a8 60%, #8c6f3f 100%); }
.art-8 { background:
  radial-gradient(120% 90% at 30% 30%, #ecd9f0 0%, #a48bbf 55%, #4d3766 100%); }

/* ===== Deals ===== */
.deals { background: linear-gradient(180deg, #fff 0%, var(--bg) 100%); }
.deals-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
  min-height: 460px;
}
.deal {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--ink);
  color: #fff;
  display: flex; flex-direction: column; justify-content: flex-end;
  padding: 28px;
  isolation: isolate;
  min-height: 220px;
}
.deal::before {
  content: "";
  position: absolute; inset: 0;
  z-index: -1;
}
.deal::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0) 30%, rgba(0,0,0,.55) 100%);
  z-index: -1;
}
.deal-1 { grid-row: span 2; }
.deal-1::before { background:
  radial-gradient(120% 90% at 30% 30%, #46594b 0%, #1f2b22 80%); }
.deal-2::before { background:
  radial-gradient(120% 90% at 60% 40%, #b6843e 0%, #5a3a14 100%); }
.deal-3::before { background:
  linear-gradient(150deg, #8a4a3a 0%, #3a1a14 100%); }
.deal-4::before { background:
  radial-gradient(120% 90% at 60% 30%, #5d6d80 0%, #1c2530 100%); }
.deal-5::before { background:
  linear-gradient(135deg, #6b5b8a 0%, #2d2240 100%); }

.deal .pct {
  position: absolute; top: 20px; left: 20px;
  background: #fff; color: var(--ink);
  font-weight: 700; font-size: 13px;
  padding: 6px 12px; border-radius: 999px;
}
.deal h3 {
  font-family: var(--font-serif);
  font-size: clamp(20px, 2.2vw, 30px);
  font-weight: 500;
  margin: 0 0 6px;
}
.deal-1 h3 { font-size: clamp(28px, 3.2vw, 42px); }
.deal p { margin: 0 0 14px; color: rgba(255,255,255,.85); font-size: 14px; }
.deal a {
  display: inline-flex; align-items: center; gap: 6px;
  align-self: flex-start;
  background: #fff; color: var(--ink);
  text-decoration: none;
  font-size: 14px; font-weight: 600;
  padding: 9px 16px; border-radius: 999px;
}
.deal a:hover { background: var(--accent-soft); }

/* ===== Editorial ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: auto auto;
  gap: 24px;
}
.story {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
}
.story-feature {
  grid-row: span 2;
}
.story-media {
  aspect-ratio: 16 / 10;
  background: var(--bg);
}
.story-feature .story-media { aspect-ratio: 4 / 3; }
.story-media[data-art="studio"] { background:
  linear-gradient(135deg, #efe6d2 0%, #b89b66 60%, #5a4321 100%); }
.story-media[data-art="kitchen"] { background:
  radial-gradient(120% 90% at 40% 35%, #f3efe5 0%, #c2b893 60%, #6b5e36 100%); }
.story-media[data-art="travel"] { background:
  linear-gradient(160deg, #d6deea 0%, #6f8aaa 60%, #2c405c 100%); }

.story-body { padding: 20px 22px 24px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.story .tag {
  display: inline-block;
  font-size: 11.5px; font-weight: 600;
  letter-spacing: .08em; text-transform: uppercase;
  color: var(--accent);
  margin: 0;
}
.story h3 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: 20px;
  line-height: 1.25;
  margin: 0;
}
.story-feature h3 { font-size: 26px; }
.story h3 a { text-decoration: none; color: var(--ink); }
.story h3 a:hover { text-decoration: underline; text-underline-offset: 3px; }
.story p { margin: 0; color: var(--ink-2); font-size: 14.5px; }
.story .meta { color: var(--muted); font-size: 13px; margin-top: auto; padding-top: 4px; }

/* ===== Newsletter ===== */
.newsletter {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 64px 24px;
  margin-top: 24px;
}
.newsletter-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(28px, 3.4vw, 40px);
  margin: 0 0 10px;
}
.newsletter p { margin: 0; color: rgba(255,255,255,.85); }
.newsletter-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: center;
}
.newsletter-form input {
  grid-column: 1;
  padding: 14px 18px;
  border-radius: 999px;
  border: 1.5px solid rgba(255,255,255,.4);
  background: rgba(255,255,255,.08);
  color: #fff;
  font: inherit; font-size: 15px;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,.65); }
.newsletter-form input:focus {
  outline: none;
  border-color: #fff;
  background: rgba(255,255,255,.15);
  box-shadow: 0 0 0 3px rgba(255,255,255,.25);
}
.newsletter-form input[aria-invalid="true"] {
  border-color: #ffd0c2;
  background: rgba(255, 200, 180, .12);
}
.newsletter-form .btn-primary {
  grid-column: 2;
  background: #fff; color: var(--accent); border-color: #fff;
}
.newsletter-form .btn-primary:hover { background: #f3efe6; border-color: #f3efe6; }
.form-help, .form-status {
  grid-column: 1 / -1;
  margin: 0;
  font-size: 13px;
  color: rgba(255,255,255,.8);
  min-height: 1.2em;
}
.form-status.error { color: #ffd9c8; font-weight: 600; }
.form-status.success { color: #d8f0dc; font-weight: 600; }

/* ===== Footer ===== */
.site-footer {
  background: #0f1113;
  color: #cfd2d6;
  padding: 56px 24px 24px;
  margin-top: 0;
}
.footer-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 36px;
}
.footer-brand .brand-word { color: #fff; }
.footer-brand p { margin: 8px 0 0; color: #9ea3aa; max-width: 32ch; }
.site-footer h2 {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: #fff;
  margin: 0 0 12px;
}
.site-footer ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.site-footer a { color: #cfd2d6; text-decoration: none; font-size: 14.5px; }
.site-footer a:hover { color: #fff; text-decoration: underline; text-underline-offset: 3px; }
.footer-bottom {
  max-width: var(--maxw); margin: 36px auto 0;
  padding-top: 20px; border-top: 1px solid #232629;
  font-size: 13px; color: #8a8f96;
}

/* ===== Toast ===== */
.toast {
  position: fixed;
  left: 50%; bottom: 24px;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink); color: #fff;
  padding: 12px 18px;
  border-radius: 999px;
  font-size: 14px; font-weight: 500;
  box-shadow: var(--shadow-md);
  opacity: 0; pointer-events: none;
  transition: opacity .2s ease, transform .2s ease;
  z-index: 100;
  max-width: calc(100vw - 40px);
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .deals-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto auto auto; }
  .deal-1 { grid-column: span 2; grid-row: span 1; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-feature { grid-column: span 2; grid-row: auto; }
  .story-feature .story-media { aspect-ratio: 16 / 9; }
}
@media (max-width: 820px) {
  .header-inner {
    grid-template-columns: auto auto;
    grid-template-areas:
      "brand actions"
      "nav nav";
    row-gap: 10px;
  }
  .brand { grid-area: brand; }
  .header-actions { grid-area: actions; }
  .primary-nav { grid-area: nav; overflow-x: auto; }
  .primary-nav ul { justify-content: flex-start; flex-wrap: nowrap; }
  .search-form input { width: 120px; }
  .hero {
    grid-template-columns: 1fr;
    padding-top: 40px;
    gap: 32px;
  }
  .hero-art { order: -1; min-height: 260px; }
  .product-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
  .deals-grid { grid-template-columns: 1fr; min-height: 0; }
  .deal-1 { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story-feature { grid-column: auto; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 24px; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .section { padding: 56px 18px; }
  .hero { padding: 32px 18px; }
  .header-inner { padding: 12px 16px; }
  .search-form { display: none; }
  .product-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
  .add-btn { font-size: 13px; padding: 9px 12px; }
  .footer-inner { grid-template-columns: 1fr; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .add-btn, .icon-btn, .search-form button, .deal a, .newsletter-form .btn-primary {
    border: 1px solid ButtonBorder;
  }
  .product, .story, .search-form, .site-header { border-color: CanvasText; }
  .brand-mark, .icon-btn svg, .search-form button svg { color: ButtonText; }
}

