+  radial-gradient(120% 90% at 60% 30%, #e6efe9 0%, #8aa896 55%, #2f4a3c 100%); }
+.art-7 { background:
+  linear-gradient(150deg, #f4f1ec 0%, #cdc0a8 60%, #8c6f3f 100%); }
+.art-8 { background:
+  radial-gradient(120% 90% at 30% 30%, #ecd9f0 0%, #a48bbf 55%, #4d3766 100%); }
+
+/* ===== Deals ===== */
+.deals { background: linear-gradient(180deg, #fff 0%, var(--bg) 100%); }
+.deals-grid {
+  list-style: none; padding: 0; margin: 0;
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr;
+  grid-template-rows: 1fr 1fr;
+  gap: 20px;
+  min-height: 460px;
+}
+.deal {
+  position: relative;
+  border-radius: var(--radius);
+  overflow: hidden;
+  background: var(--ink);
+  color: #fff;
+  display: flex; flex-direction: column; justify-content: flex-end;
+  padding: 28px;
+  isolation: isolate;
+  min-height: 220px;
+}
+.deal::before {
+  content: "";
+  position: absolute; inset: 0;
+  z-index: -1;
+}
+.deal::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, rgba(0,0,0,0) 30%, rgba(0,0,0,.55) 100%);
+  z-index: -1;
+}
+.deal-1 { grid-row: span 2; }
+.deal-1::before { background:
+  radial-gradient(120% 90% at 30% 30%, #46594b 0%, #1f2b22 80%); }
+.deal-2::before { background:
+  radial-gradient(120% 90% at 60% 40%, #b6843e 0%, #5a3a14 100%); }
+.deal-3::before { background:
+  linear-gradient(150deg, #8a4a3a 0%, #3a1a14 100%); }
+.deal-4::before { background:
+  radial-gradient(120% 90% at 60% 30%, #5d6d80 0%, #1c2530 100%); }
+.deal-5::before { background:
+  linear-gradient(135deg, #6b5b8a 0%, #2d2240 100%); }
+
+.deal .pct {
+  position: absolute; top: 20px; left: 20px;
+  background: #fff; color: var(--ink);
+  font-weight: 700; font-size: 13px;
+  padding: 6px 12px; border-radius: 999px;
+}
+.deal h3 {
+  font-family: var(--font-serif);
+  font-size: clamp(20px, 2.2vw, 30px);
+  font-weight: 500;
+  margin: 0 0 6px;
+}
+.deal-1 h3 { font-size: clamp(28px, 3.2vw, 42px); }
+.deal p { margin: 0 0 14px; color: rgba(255,255,255,.85); font-size: 14px; }
+.deal a {
+  display: inline-flex; align-items: center; gap: 6px;
+  align-self: flex-start;
+  background: #fff; color: var(--ink);
+  text-decoration: none;
+  font-size: 14px; font-weight: 600;
+  padding: 9px 16px; border-radius: 999px;
+}
+.deal a:hover { background: var(--accent-soft); }
+
+/* ===== Editorial ===== */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr;
+  grid-template-rows: auto auto;
+  gap: 24px;
+}
+.story {
+  background: var(--surface);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex; flex-direction: column;
+}
+.story-feature {
+  grid-row: span 2;
+}
+.story-media {
+  aspect-ratio: 16 / 10;
+  background: var(--bg);
+}
+.story-feature .story-media { aspect-ratio: 4 / 3; }
+.story-media[data-art="studio"] { background:
+  linear-gradient(135deg, #efe6d2 0%, #b89b66 60%, #5a4321 100%); }
+.story-media[data-art="kitchen"] { background:
+  radial-gradient(120% 90% at 40% 35%, #f3efe5 0%, #c2b893 60%, #6b5e36 100%); }
+.story-media[data-art="travel"] { background:
+  linear-gradient(160deg, #d6deea 0%, #6f8aaa 60%, #2c405c 100%); }
+
+.story-body { padding: 20px 22px 24px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
+.story .tag {
+  display: inline-block;
+  font-size: 11.5px; font-weight: 600;
+  letter-spacing: .08em; text-transform: uppercase;
+  color: var(--accent);
+  margin: 0;
+}
+.story h3 {
+  font-family: var(--font-serif);
+  font-weight: 500;
+  font-size: 20px;
+  line-height: 1.25;
+  margin: 0;
+}
+.story-feature h3 { font-size: 26px; }
+.story h3 a { text-decoration: none; color: var(--ink); }
+.story h3 a:hover { text-decoration: underline; text-underline-offset: 3px; }
+.story p { margin: 0; color: var(--ink-2); font-size: 14.5px; }
+.story .meta { color: var(--muted); font-size: 13px; margin-top: auto; padding-top: 4px; }
+
+/* ===== Newsletter ===== */
+.newsletter {
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 64px 24px;
+  margin-top: 24px;
+}
+.newsletter-inner {
+  max-width: var(--maxw);
+  margin: 0 auto;
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 40px;
+  align-items: center;
+}
+.newsletter h2 {
+  font-family: var(--font-serif);
+  font-weight: 500;
+  font-size: clamp(28px, 3.4vw, 40px);
+  margin: 0 0 10px;
+}
+.newsletter p { margin: 0; color: rgba(255,255,255,.85); }
+.newsletter-form {
+  display: grid;
+  grid-template-columns: 1fr auto;
+  gap: 10px;
+  align-items: center;
+}
+.newsletter-form input {
+  grid-column: 1;
+  padding: 14px 18px;
+  border-radius: 999px;
+  border: 1.5px solid rgba(255,255,255,.4);
+  background: rgba(255,255,255,.08);
+  color: #fff;
+  font: inherit; font-size: 15px;
+}
+.newsletter-form input::placeholder { color: rgba(255,255,255,.65); }
+.newsletter-form input:focus {
+  outline: none;
+  border-color: #fff;
+  background: rgba(255,255,255,.15);
+  box-shadow: 0 0 0 3px rgba(255,255,255,.25);
+}
+.newsletter-form input[aria-invalid="true"] {
+  border-color: #ffd0c2;
+  background: rgba(255, 200, 180, .12);
+}
+.newsletter-form .btn-primary {
+  grid-column: 2;
+  background: #fff; color: var(--accent); border-color: #fff;
+}
+.newsletter-form .btn-primary:hover { background: #f3efe6; border-color: #f3efe6; }
+.form-help, .form-status {
+  grid-column: 1 / -1;
+  margin: 0;
+  font-size: 13px;
+  color: rgba(255,255,255,.8);
+  min-height: 1.2em;
+}
+.form-status.error { color: #ffd9c8; font-weight: 600; }
+.form-status.success { color: #d8f0dc; font-weight: 600; }
+
+/* ===== Footer ===== */
+.site-footer {
+  background: #0f1113;
+  color: #cfd2d6;
+  padding: 56px 24px 24px;
+  margin-top: 0;
+}
+.footer-inner {
+  max-width: var(--maxw);
+  margin: 0 auto;
+  display: grid;
+  grid-template-columns: 1.4fr repeat(3, 1fr);
+  gap: 36px;
+}
+.footer-brand .brand-word { color: #fff; }
+.footer-brand p { margin: 8px 0 0; color: #9ea3aa; max-width: 32ch; }
+.site-footer h2 {
+  font-family: var(--font-sans);
+  font-size: 13px;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .1em;
+  color: #fff;
+  margin: 0 0 12px;
+}
+.site-footer ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
+.site-footer a { color: #cfd2d6; text-decoration: none; font-size: 14.5px; }
+.site-footer a:hover { color: #fff; text-decoration: underline; text-underline-offset: 3px; }
+.footer-bottom {
+  max-width: var(--maxw); margin: 36px auto 0;
+  padding-top: 20px; border-top: 1px solid #232629;
+  font-size: 13px; color: #8a8f96;
+}
+
+/* ===== Toast ===== */
+.toast {
+  position: fixed;
+  left: 50%; bottom: 24px;
+  transform: translateX(-50%) translateY(20px);
+  background: var(--ink); color: #fff;
+  padding: 12px 18px;
+  border-radius: 999px;
+  font-size: 14px; font-weight: 500;
+  box-shadow: var(--shadow-md);
+  opacity: 0; pointer-events: none;
+  transition: opacity .2s ease, transform .2s ease;
+  z-index: 100;
+  max-width: calc(100vw - 40px);
+}
+.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
+
+/* ===== Responsive ===== */
+@media (max-width: 1024px) {
+  .product-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
+  .deals-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto auto auto; }
+  .deal-1 { grid-column: span 2; grid-row: span 1; }
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .story-feature { grid-column: span 2; grid-row: auto; }
+  .story-feature .story-media { aspect-ratio: 16 / 9; }
+}
+@media (max-width: 820px) {
+  .header-inner {
+    grid-template-columns: auto auto;
+    grid-template-areas:
+      "brand actions"
+      "nav nav";
+    row-gap: 10px;
+  }
+  .brand { grid-area: brand; }
+  .header-actions { grid-area: actions; }
+  .primary-nav { grid-area: nav; overflow-x: auto; }
+  .primary-nav ul { justify-content: flex-start; flex-wrap: nowrap; }
+  .search-form input { width: 120px; }
+  .hero {
+    grid-template-columns: 1fr;
+    padding-top: 40px;
+    gap: 32px;
+  }
+  .hero-art { order: -1; min-height: 260px; }
+  .product-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
+  .deals-grid { grid-template-columns: 1fr; min-height: 0; }
+  .deal-1 { grid-column: auto; }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .story-feature { grid-column: auto; }
+  .newsletter-inner { grid-template-columns: 1fr; gap: 24px; }
+  .footer-inner { grid-template-columns: 1fr 1fr; }
+}
+@media (max-width: 480px) {
+  .section { padding: 56px 18px; }
+  .hero { padding: 32px 18px; }
+  .header-inner { padding: 12px 16px; }
+  .search-form { display: none; }
+  .product-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
+  .add-btn { font-size: 13px; padding: 9px 12px; }
+  .footer-inner { grid-template-columns: 1fr; }
+}
+
+/* Reduced motion */
+@media (prefers-reduced-motion: reduce) {
